"use client";

import type React from "react";
import { AbsoluteFill, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type AccordionUnfoldElementId,
  accordionUnfoldTimeline,
} from "./timeline";

export type AccordionUnfoldProps = {
  /** Lockup printed across the card. Use a color that reads on `color`. Falls back to a placeholder "remocn" lockup. */
  children?: React.ReactNode;
  /** Number of vertical pleats. */
  panels?: number;
  /** Paper color of the card. */
  color?: string;
  /** Darkness of the panels facing away from the light, 0 to 1. */
  shade?: number;
  backgroundColor?: string;
  /** Fold angle of each pleat at the start, in degrees. */
  foldAngle?: number;
  speed?: number;
  /**
   * Moves, trims or stretches the card's lift and the unfold, by the ids in
   * `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<AccordionUnfoldElementId>;
};

export const accordionUnfoldDefaults = {
  panels: 6,
  color: "#FFFFFF",
  shade: 0.55,
  backgroundColor: "#111111",
  foldAngle: 82,
  speed: 1,
};

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const PLACEHOLDER_FONT =
  "-apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Helvetica, Arial, sans-serif";

// Neutral lockup shown when no children are passed.
function PlaceholderLockup({
  mark,
  dot,
  text,
  scale = 1,
}: {
  mark: string;
  dot: string;
  text: string;
  scale?: number;
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 28 * scale }}>
      <div
        style={{
          width: 120 * scale,
          height: 120 * scale,
          borderRadius: 32 * scale,
          backgroundColor: mark,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 36 * scale,
            height: 36 * scale,
            borderRadius: "50%",
            backgroundColor: dot,
          }}
        />
      </div>
      <span
        style={{
          fontFamily: PLACEHOLDER_FONT,
          fontSize: 104 * scale,
          fontWeight: 800,
          letterSpacing: "-0.04em",
          color: text,
        }}
      >
        remocn
      </span>
    </div>
  );
}

export function AccordionUnfold(props: AccordionUnfoldProps) {
  const {
    children,
    panels,
    color,
    shade,
    backgroundColor,
    foldAngle,
    speed,
    timing,
  } = { ...accordionUnfoldDefaults, ...props };
  const glide = useGlide();
  const frame = useSceneFrame();
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const t = frame * Math.max(0, speed);
  const tl = useTimeline(
    accordionUnfoldTimeline,
    props,
    durationInFrames * Math.max(0, speed),
    timing,
  );
  const card = tl.get("card");
  const unfold = tl.get("unfold");
  const n = Math.max(2, Math.round(panels));
  const cardW = Math.round(Math.min(width * 0.66, height * 1.3));
  const cardH = Math.round(Math.min(height * 0.4, cardW * 0.4));
  const pw = cardW / n;

  const open = spring({
    frame: t - unfold.start,
    fps,
    config: { damping: 15, stiffness: 70, mass: 0.9 },
  });
  const theta = foldAngle * (1 - open);
  const rad = (theta * Math.PI) / 180;
  // Keep the pleated stack centered while its projected width grows.
  const shift = (cardW - cardW * Math.cos(rad)) / 2;
  const lift = interpolate(t, [card.start, card.end], [0.92, 1], clamp);
  const appear = interpolate(
    t,
    [card.start, card.start + card.beat("fade")],
    [0, 1],
    clamp,
  );
  const flat = Math.abs(theta) < 0.3;
  // The pleats exist only while the card lifts and unfolds; once flat, the
  // card is plain again and only a sub-pixel slide on x is left.
  const folding = (lift < 1 && speed > 0) || (!flat && t > unfold.start);

  const print = (offset: number) => (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: -offset,
        width: cardW,
        height: cardH,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {children ?? (
        <PlaceholderLockup
          mark={backgroundColor}
          dot={color}
          text={backgroundColor}
          scale={0.8}
        />
      )}
    </div>
  );

  const panel = (i: number): React.ReactNode => {
    if (i >= n) return null;
    const angle = i === 0 ? theta : (i % 2 === 1 ? -2 : 2) * theta;
    const facing = i % 2 === 0 ? 1 : -1;
    const tilt = Math.abs(Math.sin(rad));
    const darkness = facing > 0 ? shade * tilt : shade * 0.25 * tilt;
    return (
      <div
        style={{
          position: "absolute",
          top: 0,
          left: i === 0 ? 0 : pw,
          width: pw,
          height: cardH,
          transformOrigin: "0% 50%",
          transform: `rotateY(${angle}deg)`,
          transformStyle: "preserve-3d",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            // A hair of bleed hides antialiased seams between pleats.
            width: pw + 1,
            overflow: "hidden",
            backgroundColor: color,
            backfaceVisibility: "hidden",
          }}
        >
          {print(i * pw)}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                facing > 0
                  ? `linear-gradient(90deg, rgba(0,0,0,${darkness * 0.6}), rgba(0,0,0,${darkness}))`
                  : `linear-gradient(90deg, rgba(255,255,255,${0.12 * tilt}), rgba(0,0,0,${darkness}))`,
            }}
          />
        </div>
        {panel(i + 1)}
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor,
        alignItems: "center",
        justifyContent: "center",
        perspective: cardW * 1.8,
      }}
    >
      <div
        style={{
          position: "relative",
          width: cardW,
          height: cardH,
          opacity: appear,
          // The card carries the print: marked, so its text leans while the
          // card lifts and unfolds.
          transform: `translateX(${shift}px) scale(${lift})${glide(folding)}`,
          transformStyle: "preserve-3d",
        }}
      >
        {flat ? (
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: color,
              overflow: "hidden",
            }}
          >
            {print(0)}
          </div>
        ) : (
          panel(0)
        )}
      </div>
    </AbsoluteFill>
  );
}

import { defineTimeline } from "@/lib/remocn/timeline";

// The folded card fades in and lifts, then its pleats spring open flat.
// Frames on the 30 fps scene timeline, after `speed`. The ids are public: a
// saved `timing` prop refers to them.

export type AccordionUnfoldElementId = "card" | "unfold";

const START = 4;

// `card` fades the folded card in over `fade` and lifts it to full size over
// its length. `unfold` springs the pleats open from its start; its length is
// roughly where the spring settles.
export const accordionUnfoldTimeline = defineTimeline<
  AccordionUnfoldElementId,
  object
>(() => [
  {
    id: "card",
    lane: "Card",
    label: "Lift",
    start: 0,
    length: START + 2,
    beats: { fade: 3 },
  },
  { id: "unfold", lane: "Pleats", label: "Unfold", start: START, length: 40 },
]);
